// Search docs: keyword retrieval over the KA Docs table.
// Score = share of the question's important words that appear in a chunk,
// weighted by how rare each word is in the docs (IDF). 1 = all words found, 0 = none.
const TOP_K = 4;
const THRESHOLD = 0.35; // below this the workflow answers "I don't know" without calling the AI

const STOPWORDS = new Set(('a an the and or but if then of to in on at by for with from into over after before about as is are was were be been ' +
  'being do does did can could should would will shall may might must i we you he she it they me us our your my their this that these ' +
  'those what which who whom whose when where why how much many there here not no yes any some all each every so than too very just ' +
  'have has had get got go goes need want make also out up down its').split(' '));

function stem(w) {
  if (w.length > 5 && w.endsWith('ing')) return w.slice(0, -3);
  if (w.length > 4 && w.endsWith('ed')) return w.slice(0, -2);
  if (w.length > 4 && w.endsWith('ies')) return w.slice(0, -3) + 'y';
  if (w.length > 3 && w.endsWith('es') && !w.endsWith('ses')) return w.slice(0, -2);
  if (w.length > 3 && w.endsWith('s') && !w.endsWith('ss')) return w.slice(0, -1);
  return w;
}
function tokens(text) {
  return (String(text || '').toLowerCase().match(/[a-z0-9]+/g) || [])
    .filter(t => !STOPWORDS.has(t) && t.length > 1)
    .map(stem);
}

const asked = $('Normalize question').first().json;
const question = String(asked.question || '').trim();
const rows = $input.all().map(i => i.json).filter(r => r.chunk_id && r.text);

const docs = rows.map(r => {
  const toks = tokens(r.title + ' ' + r.section + ' ' + r.text);
  return { row: r, set: new Set(toks), toks };
});
const N = docs.length;
const df = {};
for (const d of docs) for (const t of d.set) df[t] = (df[t] || 0) + 1;
const idf = t => Math.log(1 + N / ((df[t] || 0) + 0.5));

const qTerms = [...new Set(tokens(question))];
const qWeight = qTerms.reduce((s, t) => s + idf(t), 0);

const ranked = docs.map(d => {
  const matched = qTerms.filter(t => d.set.has(t));
  const coverage = qWeight ? matched.reduce((s, t) => s + idf(t), 0) / qWeight : 0;
  const tf = matched.reduce((s, t) => s + d.toks.filter(x => x === t).length, 0);
  return { chunk_id: d.row.chunk_id, doc_id: d.row.doc_id, title: d.row.title, section: d.row.section,
           text: d.row.text, score: Math.round(coverage * 1000) / 1000, matched, tf };
}).filter(c => c.score > 0)
  .sort((a, b) => b.score - a.score || b.tf - a.tf)
  .slice(0, TOP_K);

const context = ranked.map(c =>
  '<chunk id="' + c.chunk_id + '" title="' + c.title + '" section="' + c.section + '">' + c.text + '</chunk>'
).join('\n');

return [{ json: {
  question,
  channel: asked.channel,
  top_score: ranked.length ? ranked[0].score : 0,
  threshold: THRESHOLD,
  retrieved: ranked.map(c => ({ chunk_id: c.chunk_id, doc_id: c.doc_id, title: c.title, section: c.section, score: c.score })),
  retrieved_ids: ranked.map(c => c.chunk_id).join(', '),
  query_terms: qTerms.join(', '),
  context
} }];

// Check citations: accept the AI answer only if it is valid JSON and every cited
// chunk_id is one of the chunks that the search actually found. Otherwise answer "I don't know".
const IDK = "I don't know based on the documentation.";
const found = $('Search docs').first().json;
const allowed = new Set(found.retrieved.map(c => c.chunk_id));
const ai = $input.first().json;

// The Anthropic node can return the text in different fields; collect whatever is there.
function aiText(j) {
  if (typeof j.merged_response === 'string') return j.merged_response;
  if (Array.isArray(j.content)) return j.content.filter(p => p && p.type === 'text').map(p => p.text).join('');
  if (typeof j.text === 'string') return j.text;
  if (typeof j.output === 'string') return j.output;
  return '';
}
function parse(text) {
  const start = text.indexOf('{');
  const end = text.lastIndexOf('}');
  if (start === -1 || end <= start) return null;
  try { return JSON.parse(text.slice(start, end + 1)); } catch (e) { return null; }
}

const raw = aiText(ai);
const reply = parse(raw);
let status, answer, sources = [], reason = '';

if (ai.error || !reply) {
  status = 'ai_error'; answer = IDK; reason = ai.error ? 'AI call failed' : 'AI reply was not valid JSON';
} else if (reply.not_covered === true) {
  status = 'not_covered'; answer = IDK; reason = 'AI said the chunks do not answer the question';
} else {
  const cited = Array.isArray(reply.sources) ? reply.sources.map(s => String(s).trim()) : [];
  const unknown = cited.filter(s => !allowed.has(s));
  const text = String(reply.answer || '').trim();
  if (!text) {
    status = 'citation_failed'; answer = IDK; reason = 'empty answer';
  } else if (cited.length === 0) {
    status = 'citation_failed'; answer = IDK; reason = 'answer without sources';
  } else if (unknown.length) {
    status = 'citation_failed'; answer = IDK; reason = 'cited chunks that were not retrieved: ' + unknown.join(', ');
  } else {
    status = 'answered'; answer = text; sources = [...new Set(cited)];
  }
}

return [{ json: {
  question: found.question,
  channel: found.channel,
  answer,
  sources: sources.join(', '),
  retrieved_ids: found.retrieved_ids,
  top_score: found.top_score,
  status,
  reason
} }];
